# Define the range and the number of colors
N = 44
K = 4

def check_solution(coloring):
    """Checks if the current coloring is valid (no monochromatic solutions to x + y = z)"""
    colors = {}
    for i in range(1, N + 1):
        c = coloring[i]
        if c not in colors:
            colors[c] = set()
        colors[c].add(i)

    for c in colors:
        S = list(colors[c])
        # Check all pairs (x, y) from S
        for i in range(len(S)):
            for j in range(len(S)):
                x = S[i]
                y = S[j]
                z = x + y
                # Check if z is in the set S (and within the defined range N)
                if z <= N and z in colors[c]:
                    return False # Found monochromatic solution
    return True # No monochromatic solution found

def solve_coloring():
    """Uses backtracking to attempt to find a 4-coloring."""
    coloring = {} # Maps number i to color c (1 to 4)

    def backtrack(i):
        if i > N:
            # We successfully colored all elements. Now check the constraints.
            if check_solution(coloring):
                return coloring # Found a valid coloring
            return None

        # Try assigning each of the K colors to element i
        for c in range(1, K + 1):
            coloring[i] = c

            # Quick constraint check before diving deeper (optimization)
            # Since x+y=z involves three elements, a full check is better done at the end,
            # but we can check partial violations for early pruning.

            # For simplicity and focus on the overall search, we rely on the final check,
            # although a proper CSP would prune aggressively here.

            result = backtrack(i + 1)
            if result is not None:
                return result

            # Backtrack
            del coloring[i]

        return None

    return backtrack(1)

# Run the search
print("Starting coloring search...")
solution = solve_coloring()

if solution:
    print("SUCCESS: A 4-coloring avoiding monochromatic x+y=z was found.")
    # Optional: print the coloring for verification
    # print(solution)
else:
    print("FAILURE: No 4-coloring avoiding monochromatic x+y=z was found for {1, ..., 44}.")
